body.script:
/* =================================
   ЭЛЕМЕНТЫ
================================= */

const chat =
    document.getElementById("chat");

const welcome =
    document.getElementById("welcome");

const input =
    document.getElementById("input");

const send =
    document.getElementById("send");

const newChat =
    document.getElementById("newChat");


/* =================================
   ИСТОРИЯ ДИАЛОГА
================================= */

let messages = [];

let waiting = false;


/* =================================
   INPUT
================================= */

input.addEventListener(
    "input",
    function(){

        send.disabled =
            waiting ||
            !input.value.trim();

        input.style.height = "auto";

        input.style.height =
            Math.min(
                input.scrollHeight,
                130
            ) + "px";
    }
);


/* =================================
   ENTER
================================= */

input.addEventListener(
    "keydown",
    function(event){

        if(
            event.key === "Enter" &&
            !event.shiftKey
        ){

            event.preventDefault();

            if(!send.disabled){
                sendMessage();
            }

        }

    }
);


/* =================================
   НОВЫЙ ЧАТ
================================= */

newChat.addEventListener(
    "click",
    function(){

        messages = [];

        chat.innerHTML = "";

        chat.appendChild(welcome);

        welcome.style.display = "flex";

        input.value = "";

        input.style.height = "auto";

        send.disabled = true;

        input.focus();

    }
);


/* =================================
   ДОБАВИТЬ СООБЩЕНИЕ
================================= */

function addMessage(
    text,
    type
){

    if(welcome.parentNode){
        welcome.style.display = "none";
    }


    const wrapper =
        document.createElement("div");

    wrapper.className =
        "message " + type;


    const bubble =
        document.createElement("div");

    bubble.className =
        "bubble";

    bubble.textContent = text;


    wrapper.appendChild(bubble);

    chat.appendChild(wrapper);


    chat.scrollTop =
        chat.scrollHeight;


    return bubble;
}


/* =================================
   ПЕЧАТАЮЩИЙ ИНДИКАТОР
================================= */

function addTyping(){

    const wrapper =
        document.createElement("div");

    wrapper.className =
        "message ai";

    wrapper.id =
        "typingMessage";


    const bubble =
        document.createElement("div");

    bubble.className =
        "bubble typing";


    bubble.innerHTML =
        "";


    wrapper.appendChild(bubble);

    chat.appendChild(wrapper);


    chat.scrollTop =
        chat.scrollHeight;
}


/* =================================
   УДАЛИТЬ TYPING
================================= */

function removeTyping(){

    const element =
        document.getElementById(
            "typingMessage"
        );

    if(element){
        element.remove();
    }
}


/* =================================
   ОТПРАВКА
================================= */

async function sendMessage(){

    const text =
        input.value.trim();


    if(!text || waiting){
        return;
    }


    waiting = true;

    send.disabled = true;


    /* пользователь */

    addMessage(
        text,
        "user"
    );


    messages.push({
        role:"user",
        content:text
    });


    input.value = "";

    input.style.height = "auto";


    /* typing */

    addTyping();


    try{

        const response =
            await fetch(
                "/api/chat",
                {
                    method:"POST",

                    headers:{
                        "Content-Type":
                            "application/json"
                    },

                    body:JSON.stringify({
                        messages:messages
                    })
                }
            );


        const data =
            await response.json();


        removeTyping();


        if(!response.ok){

            throw new Error(
                data.error ||
                "Ошибка сервера"
            );

        }


        const answer =
            data.answer ||
            "Я не смог сформировать ответ.";


        addMessage(
            answer,
            "ai"
        );


        messages.push({
            role:"assistant",
            content:answer
        });


    }catch(error){

        removeTyping();


        const bubble =
            addMessage(
                "Не удалось подключиться к AVIA. Проверь, запущен ли сервер.",
                "ai"
            );


        bubble.classList.add(
            "error"
        );


        console.error(error);

    }


    waiting = false;

    send.disabled =
        !input.value.trim();

    input.focus();

}


/* =================================
   КНОПКА
================================= */

send.addEventListener(
    "click",
    sendMessage
);
